INSERT INTO transfer_targets VALUES(10,'AVL','2026-summer','Modou Kéba Cissé','시세','시세',57,1944705,'LASK → Aston Villa','CB','RCB','CONFIRMED',NULL,'001100013201476027X812666',60.89999999999999858,31.19999999999999929,29,7.099999999999999645,'cb_defender','Balanced','cb_bpd','Aggressive',0.8830000000000000071,'CONFIRMED incoming: pre-contract signed summer 2025, joins for 2026/27 after a season at LASK. Measured: right-of-centre CB (60.9,31.2), Ball-Playing Defender/Aggressive fit 0.89 — same fit family as Konsa (0.88). Natural RCB cover/heir; Austrian Bundesliga level caveat. [2026-07-15 재확인] RotoWire: 공식 합류 확인(사전계약, LASK에서 2026년 여름 발효). [2026-07-15 3축+스탯 — 유지] 6경기: kp 0·xA .01·듀얼 3.8·태클 1.5·패스 84% — 진전 산출 없는 수비형, cb_defender/Balanced 처방 유지(움직임은 bpd/Aggressive .89로 콘사형 스텝아웃 — 기능축 우선). LASK 리그 수준 캐비앗. [2026-07-28 FC26 통합 확인] 숙련 cb_defender+·cb_stopper+ — bpd 마커 없음, 기능축 처방(cb_defender/Balanced)을 FC26이 지지 — 확정.','SofaScore API 25/26 전수 재수집 (2026-08-11) — player_role_map kind=measured','실측 HIGH — 25/26 전수 29경기.  커널 적합은 docs/20 회귀 게이트 통과 구현으로 산출. ⚠️ 2026-08-11 이전 값은 4~6경기 표본이었다.');
INSERT INTO transfer_targets VALUES(13,'AVL','2026-summer','Alysson','알리송',NULL,59,1631879,'Aston Villa (2026-01, Grêmio €10M)','RW','RM','OWNED',NULL,'001331015X001370003500013',83.20000000000000284,59.70000000000000284,22,6.879999999999999894,'wm_winger','Balanced','wm_widemid','Build-Up',0.8329999999999999627,'ALREADY OWNED: joined from Grêmio for €10M in January 2026; young (2006) right winger not yet in the analysis roster. Measured: genuine wide-right (83.2,59.7) — the squad''s only natural touchline RW; fit Inside Forward/Balanced 0.85. Prescription Winger/Attack to use his width+pace profile distinct from McGinn/Bowen half-space types. [2026-07-15 3축+스탯 — 유지] 6경기: xG .10·xA .03·kp .3·듀얼 3.7·드리블 1.0 — 창조 산출 미성숙 직선 윙어, winger/Attack 처방 유지(움직임 최근접은 insidefwd/Balanced .847). [2026-07-29 우측 브리프 정합 검증] 디아비 템플릿 코사인 .839, 침투 서명 전방 0.54·자기진영 0.23(하지무사·음바예보다 낮음 = 침투 빈도 열위), 터치라인 열 0.60 = 스쿼드 유일 천연 터치라인 RW. 함의: 브리프를 부분 충족하는 보유 자원이라 "우측이 절대 공백은 아니다"는 협상 레버리지. 19세로 주전 고정은 리스크.','SofaScore API 25/26 전수 재수집 (2026-08-11) — player_role_map kind=measured','실측 HIGH — 25/26 전수 22경기.  커널 적합은 docs/20 회귀 게이트 통과 구현으로 산출. ⚠️ 2026-08-11 이전 값은 4~6경기 표본이었다.');
INSERT INTO transfer_targets VALUES(30,'AVL','2026-summer','Tammy Abraham','타미 아브라함',NULL,60,610766,'Aston Villa','ST','ST','OWNED',NULL,'239324777256X732212211410',47.39999999999999858,59.0,25,6.950000000000000177,'st_target','Attack','st_false9','Attack',0.6430000000000000159,'ALREADY OWNED: 2026-01-27 베식타슈에서 ~£18m로 빌라 복귀(1일 만에 재이적), 그 시즌 유로파리그 우승. 여름 루머 대상이 아니라 보유 선수(알리송과 동일 케이스) — 사용자 요청으로 OWNED ST 옵션으로 편입. 실측(반시즌 통틀어 45분+ 4경기 전부 ST): 중앙-약간좌측·깊은 풋프린트 (47.4,59.0), 평균 6.85. 최근접 st_false9/Attack 0.52 — 왓킨스(st_advanced 자기커널)·기라시 0.80·브로베이 0.75·파르도 0.87보다 명확히 낮음. 처방은 타깃/홀드업 아키타입 반영 st_target/Attack. 표본 캐비앳: 왓킨스의 로테이션 백업이라 45분+ 경기가 반시즌 4경기뿐이고 전부 교체 출전(추격 상황 드롭) → 깊은 편향된 풋프린트, 선발 표본 아님. [2026-07-15 3축+스탯 — 유지] 6경기: xG .25·3골·kp 1.0·드리블 0 — 타깃형 피니셔, st_target/Attack(공중 플랜B, obs#19) 유지.','SofaScore API 25/26 전수 재수집 (2026-08-11) — player_role_map kind=measured','실측 HIGH — 25/26 전수 25경기.  커널 적합은 docs/20 회귀 게이트 통과 구현으로 산출. ⚠️ 2026-08-11 이전 값은 4~6경기 표본이었다.');
INSERT INTO transfer_targets VALUES(77,'AVL','2026-summer','Johan Manzambi','만잠비','만잠비',55,1518931,'SC Freiburg','CM','LDM','CONFIRMED',NULL,'33423X9565897636965322311',43.60000000000000142,51.79999999999999716,56,7.200000000000000177,'dm_dlp','Roaming','dm_dlp','Roaming',0.7129999999999999672,'완전 box-to-box, 중앙 전역 커버(온아나 대체). 실측 6경기(분데스리가, 363pt) 중심 tool(44,52). 커널 fit LDM dm_dlp/Roaming 0.812 (RDM는 0.544로 약함 → 좌중앙 성향, LDM 전용). 평균 7.62 최상. [2026-07-14 확정] 빌라 합류 확정(사용자 확인). [2026-07-15 재확인] Romano "here we go": €60m+ 구두합의, 개인조건 완료. 뉴캐슬 £49m 구두합의를 히잭. 아직 공식 발표(메디컬) 전 단계. [2026-07-15 3축+스탯 — 유지] 6경기: 듀얼 7.5(후보군 1위)·xG .18·xA .16·태클 1.8·평점 7.40 — 박투박+창조 겸비(오나나 공백 임무에도 부합), dlp/Roaming 유지. [2026-07-17 재확인] 메디컬 완료(7/16), Romano "몇 시간 내 발표". Visit Rwanda 스폰서 관련 잡음(DRC 가족사) 해소, 5년 계약 — 클럽 레코드 £50m+. [2026-07-18 재확인] 공식 발표 완료(7/17 저녁) — £59.5m(€70m) 클럽 레코드, 장기계약. 뉴캐슬 하이잭 최종 성사. [2026-07-21 멀티포지션] CAM(대표팀 전진 실측 0.817)·LM(재배치 0.700) 행 추가 — 슬롯별 별도 그리드 참조. [2026-07-28 FC26 통합 확인] LDM: 숙련 dm_dlp+·cm_dlp+가 처방과 일치 — 확정. 테크니컬 PS·드리블85.','SofaScore API 25/26 전수 재수집 (2026-08-11) — player_role_map kind=measured','실측 HIGH — 25/26 전수 56경기. 클럽(프라이부르크) 44경기 통합 — 딥 역할 표본 커널 적합은 docs/20 회귀 게이트 통과 구현으로 산출. ⚠️ 2026-08-11 이전 값은 4~6경기 표본이었다.');
INSERT INTO transfer_targets VALUES(91,'AVL','2026-summer','João Palhinha',NULL,'팔리냐',75,364612,'Bayern Munich','DM','LDM','DEAD (벤피카 이적 합의 — 바이에른-벤피카 €15m+€5m 클럽 간 합의, 2026-08-20 SIC/O Jogo)','2026-08-20','012113536536797368X712431',57.0799999999999983,44.96000000000000085,34,7.160000000000000142,'dm_dlp','Roaming','dm_dlp','Roaming',0.7089999999999999636,unistr('[2026-08-21 DEAD 확정 + 복원 트리거 폐기] ⭐ 목적지가 제3자로 결론났다. **바이에른-벤피카 합의 €15m + €5m 목표 보너스**(SIC Notícias 08-20) / Maisfutebol은 €14m+€5m, 최대 €20m·현실 회수 €18~19m로 적는다 — 금액은 **단일값 미채택**. 선수 측은 **4시즌 계약 · 순연봉 약 €2.5m**에 벤피카와 이해가 있고, 벤피카 총 투자는 임금 포함 약 €34m이다. **마르쿠 실바 재결합**(풀럼 시절)이 동력. ⭐⭐ 결정적으로 **선수가 빌라를 직접 거절했다** — 「뉴캐슬을 먼저, 그다음 아스톤 빌라를 거절하고 벤피카를 1순위로 뒀다」. ⭐ Romano(1티어) 08-20: 팔리냐의 **PL 이적은 이제 가능성이 낮다**, **바이에른이 빌라의 임대안을 거절하고 완전 매각만 원한다**. ⇒ 08-15 「Eberl 연화」 서술보다 최신이고 방향이 반대다. ⭐⭐ **복원 트리거 문구를 폐기한다.** 기존 문구(⑴ 빌라 정식 오퍼 ⑵ 구단 간 합의)는 08-19에 문자적으로 발동했는데 실체는 **거절된 오퍼**였고 08-20 벤피카 합의로 24시간 내 소멸했다 — 「오퍼의 존재」가 아니라 **「빌라 쪽 오퍼가 수락되었는가」**를 봐야 했다. 재정의: **복원 = ⑴ 벤피카 딜이 붕괴하고 ⑵ 1티어가 빌라-바이에른 「합의(agreement)」 또는 메디컬을 보도**할 때에 한한다. 거절된 오퍼·재개된 협상·감독 발언 연화는 복원 근거가 아니다. [대체재] 빌라 DM 결손은 실재한다 — 오나나 ACL 시즌아웃 + 주앙 고메스 종아리 부상(개막 결장). 신규 대안 후보 **Youssouf Fofana(밀란, €25m 대역)**가 등장했으나 원출처 Schira 2티어 단독 + 팰리스 경쟁이라 MEDIUM(미등재).\u000a\u000a[2026-08-22 12시] ⭐ **DEAD 근거를 구조로 확정했다** — Romano **08-20 「here we go」**: 팔리냐 벤피카행 **€14m + 최대 €5m 애드온**, 서류 교환 24시간 내. ⭐ **빌라 탈락 이유가 금액이 아니라 구조였다**: 빌라는 **임대 + 매수옵션**을 원했고 바이에른은 **완전이적만** 고집해 빌라 제안을 거절했다(Damian Vidagany 축구운영이사가 바이에른과의 협상을 공개 확인한 상태였다). ⇒ **이 실패가 08-21 고레츠카 협상 개시의 직접 원인**이고, 두 행을 인과로 함께 읽어야 한다.'),'https://www.transferfeed.com/clubs/aston-villa/15; Record(PT); GiveMeSport; SportsMole ; Plettenberg/Sky DE via onefootball·readastonvilla (2026-07-24, 재검증 07-26); Sports Mole; Yahoo Sports/Bavarian Football Works("on verge"); Jacob Tanswell(Athletic, 팟캐스트); CaughtOffside ; https://www.sport1.de/news/transfermarkt/2026/08/fc-bayern-entscheidet-sich-der-palhinha-poker-in-hongkong (2026-08-06) ; https://bulinews.com/bayern-and-aston-villa-hold-palhinha-talks-after-pre-season-friendly (Sport BILD 경유) ; https://fcbinside.de/2026/08/06/testspiel-wird-zur-transfer-buehne-jetzt-kommt-bewegung-in-den-palhinha-poker/ ; https://www.90min.de/palhinha-poker-vor-neuer-wende-bayern-testet-gegen-interessenten ; Fabrizio Romano 2026-08-12 via reddit.com/r/PrimeiraLiga/comments/1vmjlgr/ · Plettenberg/Sky Sport DE 2026-08-12 (https://www.bavarianfootballworks.com/bayern-munich-transfer-news-rumors/242430/) ; Fabrizio Romano(1티어) 2026-08-14 https://x.com/FabrizioRomano/status/2088212008759869662 ; Get German Football News 2026-08-14 https://www.getfootballnewsgermany.com/2026/joao-palhinhas-aston-villa-off/ ; bulinews 2026-08-14 https://bulinews.com/bayern-confirm-talks-aston-villa-for-palhinha-broken-down ; Football365 2026-08-14 ; Marca Diego Picó(2티어) 2026-08-14 via https://footballplace.co.uk/joao-palhinha-newcastle-transfer-aston-villa/ ; Bavarian Football Works 2026-08-14 ; Kicker 경유 에베를 원문 재확인 ; TeamTalk(3티어) 2026-08-15 21:13 UK https://www.teamtalk.com/newcastle-united/newcastle-former-tottenham-star-aston-villa-target-transfer-hijack-threat','마감: 바이에른 축은 「Die Deadline ist der 1. September um 20 Uhr」(독일어 원문). ⚠️ 벤피카 딜의 공식 발표는 미확인 — 「합의」 단계이고 선수가 바이에른과 재무 정산을 마쳐야 한다(계약 2028).');
INSERT INTO transfer_targets VALUES(92,'AVL','2026-summer','João Palhinha',NULL,'팔리냐',75,364612,'Bayern Munich','DM','RDM','DEAD (벤피카 이적 합의 — 바이에른-벤피카 €15m+€5m 클럽 간 합의, 2026-08-20 SIC/O Jogo)','2026-08-20','012113536536797368X712431',57.0799999999999983,44.96000000000000085,34,7.160000000000000142,'dm_dlp','Roaming','dm_dlp','Roaming',0.7860000000000000319,unistr('[2026-08-21 DEAD 확정 + 복원 트리거 폐기] ⭐ 목적지가 제3자로 결론났다. **바이에른-벤피카 합의 €15m + €5m 목표 보너스**(SIC Notícias 08-20) / Maisfutebol은 €14m+€5m, 최대 €20m·현실 회수 €18~19m로 적는다 — 금액은 **단일값 미채택**. 선수 측은 **4시즌 계약 · 순연봉 약 €2.5m**에 벤피카와 이해가 있고, 벤피카 총 투자는 임금 포함 약 €34m이다. **마르쿠 실바 재결합**(풀럼 시절)이 동력. ⭐⭐ 결정적으로 **선수가 빌라를 직접 거절했다** — 「뉴캐슬을 먼저, 그다음 아스톤 빌라를 거절하고 벤피카를 1순위로 뒀다」. ⭐ Romano(1티어) 08-20: 팔리냐의 **PL 이적은 이제 가능성이 낮다**, **바이에른이 빌라의 임대안을 거절하고 완전 매각만 원한다**. ⇒ 08-15 「Eberl 연화」 서술보다 최신이고 방향이 반대다. ⭐⭐ **복원 트리거 문구를 폐기한다.** 기존 문구(⑴ 빌라 정식 오퍼 ⑵ 구단 간 합의)는 08-19에 문자적으로 발동했는데 실체는 **거절된 오퍼**였고 08-20 벤피카 합의로 24시간 내 소멸했다 — 「오퍼의 존재」가 아니라 **「빌라 쪽 오퍼가 수락되었는가」**를 봐야 했다. 재정의: **복원 = ⑴ 벤피카 딜이 붕괴하고 ⑵ 1티어가 빌라-바이에른 「합의(agreement)」 또는 메디컬을 보도**할 때에 한한다. 거절된 오퍼·재개된 협상·감독 발언 연화는 복원 근거가 아니다. [대체재] 빌라 DM 결손은 실재한다 — 오나나 ACL 시즌아웃 + 주앙 고메스 종아리 부상(개막 결장). 신규 대안 후보 **Youssouf Fofana(밀란, €25m 대역)**가 등장했으나 원출처 Schira 2티어 단독 + 팰리스 경쟁이라 MEDIUM(미등재).\u000a\u000a[2026-08-22 12시] ⭐ **DEAD 근거를 구조로 확정했다** — Romano **08-20 「here we go」**: 팔리냐 벤피카행 **€14m + 최대 €5m 애드온**, 서류 교환 24시간 내. ⭐ **빌라 탈락 이유가 금액이 아니라 구조였다**: 빌라는 **임대 + 매수옵션**을 원했고 바이에른은 **완전이적만** 고집해 빌라 제안을 거절했다(Damian Vidagany 축구운영이사가 바이에른과의 협상을 공개 확인한 상태였다). ⇒ **이 실패가 08-21 고레츠카 협상 개시의 직접 원인**이고, 두 행을 인과로 함께 읽어야 한다.'),'https://www.transferfeed.com/clubs/aston-villa/15; Record(PT); GiveMeSport; SportsMole ; Plettenberg/Sky DE via onefootball·readastonvilla (2026-07-24, 재검증 07-26); Sports Mole; Yahoo Sports/Bavarian Football Works("on verge"); Jacob Tanswell(Athletic, 팟캐스트); CaughtOffside ; https://www.sport1.de/news/transfermarkt/2026/08/fc-bayern-entscheidet-sich-der-palhinha-poker-in-hongkong (2026-08-06) ; https://bulinews.com/bayern-and-aston-villa-hold-palhinha-talks-after-pre-season-friendly (Sport BILD 경유) ; https://fcbinside.de/2026/08/06/testspiel-wird-zur-transfer-buehne-jetzt-kommt-bewegung-in-den-palhinha-poker/ ; https://www.90min.de/palhinha-poker-vor-neuer-wende-bayern-testet-gegen-interessenten ; Fabrizio Romano 2026-08-12 via reddit.com/r/PrimeiraLiga/comments/1vmjlgr/ · Plettenberg/Sky Sport DE 2026-08-12 (https://www.bavarianfootballworks.com/bayern-munich-transfer-news-rumors/242430/) ; Fabrizio Romano(1티어) 2026-08-14 https://x.com/FabrizioRomano/status/2088212008759869662 ; Get German Football News 2026-08-14 https://www.getfootballnewsgermany.com/2026/joao-palhinhas-aston-villa-off/ ; bulinews 2026-08-14 https://bulinews.com/bayern-confirm-talks-aston-villa-for-palhinha-broken-down ; Football365 2026-08-14 ; Marca Diego Picó(2티어) 2026-08-14 via https://footballplace.co.uk/joao-palhinha-newcastle-transfer-aston-villa/ ; Bavarian Football Works 2026-08-14 ; Kicker 경유 에베를 원문 재확인 ; TeamTalk(3티어) 2026-08-15 21:13 UK https://www.teamtalk.com/newcastle-united/newcastle-former-tottenham-star-aston-villa-target-transfer-hijack-threat','마감: 바이에른 축은 「Die Deadline ist der 1. September um 20 Uhr」(독일어 원문). ⚠️ 벤피카 딜의 공식 발표는 미확인 — 「합의」 단계이고 선수가 바이에른과 재무 정산을 마쳐야 한다(계약 2028).');
INSERT INTO transfer_targets VALUES(95,'AVL','2026-summer','João Gomes','주앙 고메스','고메스',56,1015267,'Wolverhampton','DM/CM','LDM','CONFIRMED',NULL,'11111794665X6647968421221',47.0,47.10000000000000142,39,6.769999999999999574,'dm_dlp','Roaming','dm_dlp','Roaming',0.7630000000000000115,unistr('틸레만스 대체 영입 — 클럽간 합의(초기 £34.6m+애드온 £4.3m, 총 ~£38m), 금주 메디컬 예정. 아틀레티코행이 멘데스-구단 갈등으로 결렬된 것을 빌라가 인터셉트. [2026-07-17 실측+3축] 최근 6경기(45분+): 태클 3.7·듀얼 7.0·kp .3·xA .04 — 기능=순수 볼위너+박투박 엔진(카마라형). 움직임 최근접 dlp/Roaming .797(LDM — 우측 배치 .638로 좌측 우세). 기능축 우선(obs#31)으로 처방 dm_holding/Ball-Winning. [2026-07-18 재확인] 메디컬 금요일(7/17) 진행 — 포르투갈 캠프 이탈·귀국 확인, 개인조건 2031년 계약 합의(Schira). 공식 발표 임박. [2026-07-28 FC26 통합 확인] 기능축 우선 처방(dm_holding/Ball-Winning) 유지. 캐비앗: FC26 숙련은 boxcrasher/widehalf/dlp/cm_dlp — holding 마커 없음. 압박검증·슬라이딩태클 PS는 볼위닝 기능 지지. [2026-07-29 홀딩 처방 재검증 — 유지 확정] 현행 커널 재검산: dlp/Roaming .797 정확 재현(stale 아님), holding/Ball-Winning은 .45로 움직임 불일치. 그러나 ①실측 홀딩 동료와 직접 유사 — 온아나 그리드 .835/카마라 .805 (둘 다 움직임 코사인은 dlp .87이었으나 기능축으로 holding 처방된 동일 패턴, obs#32) ②기능=창조 전무(kp .3·xA .04) — dlp 지시는 전개 산출 없는 선수에게 공급 책임 부여하는 모순 ③요구역할=카마라 장기부상 중 앵커 대체+obs#27 블록 전제. 3축 모두 holding 지지 → dm_holding/Ball-Winning 유지. 숙련 캐비앗 대응: holding 미숙련 페널티 확인 시 차선은 dm_boxcrasher/Balanced(.701, 숙련 보유+박투박 기능 부합)이며 dlp가 아님. left-release-A 프리셋의 LDM dlp 공급 요건은 고메스 기능으로 충족 불가 — 진성 DLP형(사라·베르그발) 영입 또는 boxcrasher 절충 필요.\u000a\u000a[2026-07-31 H안] 프리셋 LDM 선발로 승격되며 처방을 dm_holding/Ball-Winning → **dm_dlp/Roaming .789**(숙련✓)로 교체. 커널 교체로 만잠비(.726)와 순위가 역전됐다(이전 만잠비 .812 > 고메스 .797). ⚠️ 캐비앗: 고메스도 기능상 볼위너이고(창조 kp .3·xA .04) 스쿼드에 진성 DLP가 없다 — 적합을 위해 기능 정합을 포기한 칸이다. [2026-08-05 역할 처방 확정 — 기존 dm_dlp/Roaming 유지] LDM(x=38) 전수 채점: dm_dlp/Roaming 0.789 → dm_dlp/Build-Up 0.714(Δ.075) → dm_boxcrasher/Balanced 0.685 → dm_holding/Roaming 0.669(Δ.120) → dm_dlp/Defend 0.578 → … → dm_holding/Ball-Winning 0.452(9/10). RDM에서는 0.680으로 LDM보다 Δ.109 낮아 **좌측 배치 확정**. [기능축 충돌은 계승 — 명시적 지불] 툴 FUNC_AXIS가 고메스를 {role:dm_holding, mode:prefer}로 두고 why에 "창조 전무(kp .3 · xA .04)로 기능축은 볼위너. 다만 dm_dlp 적합이 뚜렷이 높아 프리셋은 dlp를 채택 — 적합을 위해 기능 정합을 포기한 칸"이라 적어뒀다. 2026-08-05 이벤트 측정이 그 근거를 **독립 재현**했다: 키패스 0.30/90(FUNC_AXIS의 kp .3과 정확히 일치). dm_holding/Roaming으로 돌리면 .789→.669로 Δ.120 손실이고 동점 임계(.03)의 4배라 타이브레이커 논리로 정당화되지 않는다 → dm_dlp/Roaming 유지. [카마라와의 3선 분담] 겹침 .715로 가용 피봇 조합 중 최저(고메스↔오나나 .874가 최고 중복, 카마라↔오나나 .814, 카마라↔바클리 .806, 고메스↔바클리 .753). 좌우는 열중심 고메스 46.8 vs 카마라 62.3, 깊이는 수비3rd 고메스 7% vs 카마라 11~15%. **기능 분담은 역할 이름이 아니라 슬롯+선수 능력치가 만든다** — 이벤트 per-90: 고메스 태클 3.52 vs 카마라 2.33 / 카마라 패스 52.5 vs 42.5 · 키패스 0.93 vs 0.30 · 인터셉트 1.40 vs 0.70 · 롱볼 정확도 62.5% vs 44.0%. 즉 카마라 배급·읽기, 고메스 압박·차단. ⚠️ 표본 교란: 카마라는 25-11~26-01 빌라(4위권), 고메스는 26-02~05 울브스 — 약팀 미드필더는 구조적으로 패스가 적고 태클이 많아 교란 방향이 관측과 일치한다. 비율 지표(롱볼 정확도 18.5pp 차·키패스 3.1배)가 더 신뢰된다. ⚠️ 불변규칙 7 — 이 실측은 울브스 체제 표본이므로 개인 위치 성향 기준선으로만 쓰고 에메리 3선 구조의 근거로 쓰지 않는다. 빌라 소속 공식전 표본은 0경기다(프리시즌 5경기는 SofaScore 선수별 데이터 전건 404).'),'SofaScore API 25/26 전수 재수집 (2026-08-11) — player_role_map kind=measured','실측 HIGH — 25/26 전수 39경기.  커널 적합은 docs/20 회귀 게이트 통과 구현으로 산출. ⚠️ 2026-08-11 이전 값은 4~6경기 표본이었다.');
INSERT INTO transfer_targets VALUES(121,'AVL','2026-summer','Johan Manzambi','만잠비','만잠비',55,1518931,'SC Freiburg → Aston Villa','CM/AM','CAM','CONFIRMED',NULL,'35345X9578542261322300020',46.46999999999999887,61.39000000000000056,12,7.200000000000000177,'cam_halfwinger','Balanced','cam_halfwinger','Balanced',0.8609999999999999876,'합류확정 멀티포지션 부여: 스위스 대표팀 전진 배치 실측 — 월드컵 2경기(캐나다 8.1·알제리 7.8)+친선 2경기(호주·요르단, lineup pos=F) 통합 4경기 168pt, 중심 tool(46.5,61.4). CAM 배치 cam_halfwinger/Balanced 0.817 — 클럽(프라이부르크) 딥롤 그리드의 CAM 적합(0.575)과 달리 대표팀 전진 표본에서 10번 적합 뚜렷. 월드컵 3골(8강 진출)이 이 전진 롤에서 나옴 — 클럽 box-to-box와 별개로 세컨드 스트라이커/10번 활용 여지 실증.','SofaScore API 25/26 전수 재수집 (2026-08-11) — player_role_map kind=measured:national','실측 HIGH — 25/26 전수 12경기. 스위스 대표팀 12경기 통합 — 전진 배치 표본 커널 적합은 docs/20 회귀 게이트 통과 구현으로 산출. ⚠️ 2026-08-11 이전 값은 4~6경기 표본이었다.');
INSERT INTO transfer_targets VALUES(122,'AVL','2026-summer','Johan Manzambi','만잠비','만잠비',55,1518931,'SC Freiburg → Aston Villa','CM/AM','LM','CONFIRMED',NULL,'35345X9578542261322300020',46.46999999999999887,61.39000000000000056,12,7.200000000000000177,'wm_insidefwd','Balanced','wm_wideplm','Attack',0.6520000000000000239,'합류확정 멀티포지션 부여: LM 순수 출전 표본 없음 — 대표팀 전진 그리드(4경기 168pt)의 LM 슬롯 재배치 적합 0.700(wm_insidefwd/Balanced), 클럽 그리드 기준은 0.607. 좌 하프스페이스 커버는 가능하나 터치라인 고정형이 아닌 중앙 회귀 성향 — 로테이션/변형 옵션 등급.','SofaScore API 25/26 전수 재수집 (2026-08-11) — player_role_map kind=measured:national','실측 HIGH — 25/26 전수 12경기. 스위스 대표팀 12경기 통합 — 전진 배치 표본 커널 적합은 docs/20 회귀 게이트 통과 구현으로 산출. ⚠️ 2026-08-11 이전 값은 4~6경기 표본이었다.');
INSERT INTO transfer_targets VALUES(123,'AVL','2026-summer','Nicolas Jackson',NULL,'잭슨',76,NULL,'Chelsea','ST','ST','CONFIRMED','2026-08-28','357324X673345312211100000',45.02000000000000313,67.1700000000000017,28,6.919999999999999929,'st_false9','Attack','st_false9','Attack',0.723999999999999977,unistr('[2026-08-21 23시 · DEAD 복원] ⭐⭐ **21시의 강등을 되돌린다 — 강등 근거가 무너졌다.** 21시는 §2-1 「경쟁 클럽이 협상 단계에서 앞섬 → 한 단계 하향」을 적용해 DEAD(MEDIUM)로 내렸고, 근거는 「선수가 아틀레티코를 기다리며 빌라를 후순위로 내렸다」(insidefutbol → **Marcos Duran, 스페인 2티어**)였다. 그런데 같은 날 **Romano(1티어) 08-21 06:54**가 「첼시는 **완전이적만** 받아들이려 한다(≈£65m) … 이것이 **아틀레티코 같은 클럽들을 더 어렵게 만든다**」고 확인했고, **나폴리·토트넘은 완전이적을 원하지 않아 배제**됐다. ⇒ **첼시의 완전이적 고수는 임대 노선(ATM)을 깎고 완전이적 노선(빌라)을 살린다** — 경쟁 보정이 하향이 아니라 **대등** 방향으로 작동한다. 1티어 실체: **The Athletic — £65m은 빌라 구단 최고액**이 된다 · **Telegraph(2티어) — 재정 제약 때문에 빌라는 호가가 £60m 밑으로 내려와야 한다**(= 능동적 추진 중) · ⭐ 에메리는 **비야레알에서 잭슨을 지도한 인연**이 있고, **타미 아브라함 부진으로 ST 필요성이 커졌다**. ⛔ HIGH 불가: **1티어가 「빌라와 협상 단계」를 최신으로 확인한 건은 0건**이다.\u000a\u000a[2026-08-22 12시] MEDIUM-HIGH 유지 · ⛔⛔ **HIGH 트리거 ⒝가 미발화했고, 오히려 1티어가 미착수를 명시했다.** **Sky Sports UK(1티어) 08-21 15:50, Kaveh Solhekol + Lyall Thomas**: 「빌라는 **왓킨스를 팔면** 잭슨에게 움직일 것으로 **예상된다**」 ⇒ 단계가 **접근 이전(pre-approach)**이다. £65m·완전이적 요구는 재확인. ⭐ 이탈리아어가 3사 경쟁 구도를 정리했다 — napolinetwork가 Romano를 인용해 「나폴리는 **indietro**(뒤처졌다), 첼시는 **완전이적만** 원한다, **ATM·빌라가 그 조건으로 잔류**」, europacalcio 「**prima serve una cessione**」(나폴리는 선매각이 선행 조건). ⚠️ 그리고 **병렬 타깃이 확인됐다** — L''Équipe가 **발로건(모나코)**을 「빌라 관심은 **왓킨스의 알힐랄행에 달려 있다**」로 보도한다 ⇒ **잭슨이 그 조건부 슬롯의 단독 후보가 아니다.** [2026-08-23] 신규 취재 0건 · 재순환뿐(첼시 평가 £65m·완전이적 고수·ATM 임대 선호로 레이스 이탈). ⭐[경쟁구도] 빌라 우위 강화 — Romano가 빌라 측 의지를 「They want Jackson, trying to understand if financially they can pay what Chelsea want」로 명시(병목은 의지가 아니라 자금).\u000a\u000a[2026-08-23 21시] ⭐⭐⭐ **규정 제약 2건이 확정돼 성사 경로가 「완전이적 단일 경로」로 좁혀졌다.**\u000a**⑴ PL 「동일 구단 임대 1명」 조항 — 임대 경로가 원리적으로 막혔다.** Romano: 「빌라는 이미 가르나초를 첼시에서 임대로 받았기 때문에 이번 창에 첼시 선수를 추가로 임대할 수 없다」. PL 규정 정본 문언: 「the maximum number of loans registrable in the same season is four, and, **under no circumstances, shall more than one be from the same club at any one time**」.\u000a✅ **우리 원장으로 전제를 검증했다**: `transfer_outgoing` CHE id58 = 「Aston Villa (시즌 임대 + 조건부 의무매입)」 ⇒ 가르나초가 실제로 임대다. **조항이 실제로 발동한다.**\u000a⚠️⚠️ **크로스팀 파급(불변규칙 7)**: 같은 조항이 **토신 → 빌라**에도 동일하게 걸린다 ⇒ **토신도 임대 불가, 완전이적만 가능.** 해당 행에도 기록했다.\u000a**⑵ UEFA 45일 규칙 산술이 불리한 방향으로 확정됐다.** 로저스 이적 **발표일 07-21** 기준으로 45일을 세면 **마감일(09-01)에 체결해도 여전히 45일 안** ⇒ **스왑(player trade) 판정을 피할 수 없다.** 09시는 프랑스어 릴레이의 「45일이 09-01에 만료된다」를 원출처 부재로 미채택했는데, **그 산술 자체가 틀린 것으로 정리된다.**\u000a[경쟁구도] ⚠️ **토트넘 가속** — 사비뉴 £85m 합의 완료 + 마르무시 추진 + 각포 정체로 잭슨으로 선회. ⛔ 단 **정식 입찰 0건**이고 Romano가 「nothing close or imminent with Tottenham」로 진정시켰다. **빌라 우위 유지 — 등급 유지.** 병목은 경쟁이 아니라 **£65m 자금**이다. 토트넘·나폴리는 완전이적에 유보적이고 첼시는 완전 매각만 원한다.\u000a신규 정황: 잭슨은 **코브햄에서 1군과 분리 훈련** 중, 첼시는 「이번 주 내 정리」 희망, 알론소 구상 외. 금액 층: 첼시 £65m(=€76m) ↔ **Telegraph 「빌라는 £60m 미만이어야 한다」**(재정 제약).\u000a⚠️⚠️ **방법론 — §2-0 지표④를 Sky Sports에 적용 금지**: 오늘 실증됐다. Sky 기사 ID는 발행 순서와 단조 증가하지 않는다(`13575424` = 08-21 15:50 인데 `13574729`보다 **오래됐다**). CulturePSG·CdS·TMW·milannews에는 유효하지만 Sky에는 무효다.\u000a[2026-08-23 21시 — 등급 유지, **경쟁구도를 재작성한다**] ⛔⛔ **08-23 09시의 「ATM 레이스 이탈」 판정을 철회한다.** 두 1티어가 ATM의 **활성 참여**를 함께 말한다: ⑴ **ESPN / Rodrigo Faez 08-21 05:20 ET**(`id 49678731`, ID 단조성 검산 통과) 「Atlético Madrid **are looking to beat Aston Villa to the loan signing** of Nicolas Jackson」 ⑵ **Romano 08-21**(트윗 `2090757479231623617`) 「Aston Villa keen since August 2025 and **still there if Watkins joins Al Hilal**; **Atlético also in active talks**. Spurs and Napoli had called but **#CFC only**[완전이적만]」. ⚠️⚠️ **단 두 1티어가 「구조」에서 정면 충돌한다** — ESPN은 **임대**를 말하고 **Romano는 임대설을 「inaccurate」로 명시 부인**한다. 이 충돌은 **미해소로 남긴다.** ⭐ 2티어가 ATM의 임대 시도 자체는 보강한다 — **Marca**: Alemany가 직접 런던으로 이동해 첼시와 회동, 구조는 **임대 + 첼시의 임금 일부 분담**. estoesatleti 08-23 12:00(09시 이후 발행): **선수가 ATM에 예스**를 보냈고 첼시는 **즉시 현금이 되는 빌라 완전이적을 선호**하며 빌라의 정식 오퍼를 기다린다. ⇒ **정확한 구도는 「빌라 단독 우위」가 아니라 축의 분리다: 셀링클럽 선호=빌라(완전이적·현금) / 선수 선호=ATM(임대).** ⭐ 3의 축 토트넘: 채택 가능한 상한은 **Football Insider(2티어) 08-22 「빌라·토트넘 양측이 approaches」**까지다 — 「hijack·입찰」 문언은 Football FanCast·GiveMeSport 3티어라 미채택. 첼시-토트넘 직거래는 **2011 스콧 파커 이후 0건**. ⭐⭐ **그리고 병목은 이적료가 아니라 회계다** — **UEFA 개정 player-exchange 규정**은 45일 내 양방향 이동을 **스왑으로 간주**하고, **로저스 이적 발표가 07-21(창 42일 잔여)** 이므로 **마감일에 해도 스왑 처리될 수 있다** ⇒ 빌라가 로저스에서 잡은 처분이익이 침식된다. **가르나초가 임대+조건부 의무매입으로 구조화된 이유가 정확히 이것이다.** ⇒ **예측: 성사되면 완전이적이 아니라 임대+조건부 의무매입일 가능성이 높다.** 그런데 첼시는 현금을 원한다 — **이 구조 불일치가 이 건의 실질 교착점**이다. [2026-08-24 구조 종결·정정 2건] ⑴ **「ESPN 임대 ↔ Romano 임대 부인」은 모순이 아니었다 — 임대를 선호하는 주체는 빌라가 아니라 아틀레티코다.** Sky 13575424(08-21 15:50 Solhekol·Lyall Thomas, 1티어) 원문: 첼시는 완전이적만, ATM은 「prefers a loan arrangement」. 빌라의 임대 시나리오는 애초에 없었고 PL 「동일 구단 동시 임대 1명」(가르나초 선점) 조항과도 정합 ⇒ 구조 충돌 플래그 폐기. ⑵ ⚠️ **「ATM 레이스 이탈(AS 08-21)」 철회** — Romano 원트윗 2090757479231623617(스노플레이크 역산 08-21 11:06:42 UTC)은 「Aston Villa … still there if Watkins joins Al Hilal; **Atlético Madrid also interested and in active talks**. Spurs and Napoli had called but CFC only [permanent]」로, **탈락한 것은 토트넘·나폴리**다. 나아가 ESPN 49678731·Marca(Carlos Fernández) 08-23이 ATM의 임대 협상 지속을 1티어로 보도한다. [경쟁구도] **빌라 우위 → 대등**: 빌라는 왓킨스 매각 종속 + £65m 자금 병목, ATM은 active talks이나 첼시가 임대를 배제. 첼시 요구 £65m(€70~80m 층 병존).\u000a\u000a[2026-08-24 09시] **MEDIUM-HIGH 유지 — 단계 변화 0. 정식 입찰은 여전히 0건이다.** 첼시의 £65m 완전이적 요구(Telegraph/Matt Law, 2티어)와 Sky 13575424(08-21 15:50) 「**왓킨스 매각 시** 빌라가 움직인다」 종속 구조가 불변이다. ⭐ 그 종속의 반대편(왓킨스 유출)은 이 회차에 **1티어로 전진**했다(에메리 「I only can answer it by silence」, Sky 08-23 17:32) — 즉 **잭슨 행의 선행 조건이 진행 중**이다. ⛔ 그러나 「토트넘 hijack」 서사는 전부 3티어이고, ATM 이탈은 08-23 AS(Eduardo Burgos)로 확인되며 Sky 08-21이 그 구조적 원인(첼시 완전이적 고집 ↔ ATM 임대 선호)을 1티어로 닫았다. [경쟁구도] **빌라 우위 유지.**\u000a\u000a[2026-08-24 09시 · ⚠️정정 — 같은 회차 앞 단락의 「빌라 우위 유지」를 수정한다] ⭐⭐ **08-23의 「ATM 레이스 이탈」 판정을 「구조 교착」으로 교체한다 — 반대 방향 2티어 2건이 나왔다.** 08-23은 **AS/Eduardo Burgos 08-21**의 「sale de la carrera · ya no es una prioridad」를 채택하고 Marca의 「Alemany 런던행」을 시간순서로 눌렀는데, **그 시간순서 논거가 무효다**: **COPE 「Tiempo de Juego」(Antonio Pérez del Castillo, 스페인 2티어)** 기사는 발행 08-20 20:08이지만 **갱신이 2026-08-21 23:47로 AS보다 늦다** — 「Mateu Alemany **viajó este jueves a Londres para cerrar la cesión de Nicolas Jackson**」. ⭐⭐ **더 중요한 것은 선수 의사다** — ElDesmarque 08-21: 「Jackson ha dado luz verde… convirtiéndolo en **su destino preferido por encima de otras alternativas como el Aston Villa**」. Alemany는 **선수의 승낙을 받고** 런던에서 돌아왔다. ⇒ 두 2티어가 같은 날 정반대를 적는다 ⇒ **불변규칙 3에 따라 충돌을 그대로 기록하고 한쪽을 지우지 않는다.** ⭐ **1티어가 병목의 정체를 확정한다(Sky 13575424, 08-21 15:50)**: **첼시는 완전이적만 승인 · ATM은 임대만** 원한다. ATM은 **2027-06까지 임대**를, 첼시는 **완전매각(~€65~80m)** 을 원하고 ATM은 이적료 지불 의사가 없다. ⇒ 「ATM이 빠졌다」가 아니라 **「구조가 맞물리지 않는다」**가 정확한 서술이다.\u000a⇒ **「[경쟁구도] 빌라 우위 유지」는 ATM 축 스캔 이전에 쓴 것이라 과했다.** 수정된 판정은 **「대등 — 빌라가 구조적 우위(완전이적 수용), ATM이 선수 선호 우위(임대 희망)」**이다. §2-1 등급 보정표상 「대등」은 **등급 유지 + rationale에 경쟁 구도 명기**이므로 **MEDIUM-HIGH를 유지**한다. ⚠️ 근거 출처가 **스페인 ATM 축**임을 명기한다(불변규칙 7). [2026-08-24 20시] ⚠️ **경쟁구도 재이동: 대등 → 빌라 우위.** ATM 축이 오늘 무너졌다 — 첼시가 **ATM의 임대 오퍼를 거절**하고 「no intention of agreeing another loan」을 명시했으며(TeamTalk 08-24 10:08, Graeme Bailey), **eldesmarque 08-24가 독립 재현**한다: 「Nico Jackson … listo para dejar el Chelsea, pero **solo en un traspaso permanente, nada de cesión**」 · 「el Atleti **prefería** una cesión」(**과거시제로 이동**) · 가격 「**ronda los 70 millones**」. 게다가 **선수 본인도 임대를 원하지 않는다** — 「has little desire to spend another season away from his parent club after playing on loan at Bayern Munich last term」. 빌라는 「activamente involucrado a diario」로 **완전이적을 원하는 유일한 구조**를 추구한다. ⛔ **단 빌라의 정식 입찰은 여전히 0건**이고 문언은 「contemplating an official bid」(2티어)까지다. 신규 금액 층: 빌라는 £65m을 지불하지 않고 **「£60m 미만으로 내려와야 한다」**(재정 제약) / 첼시 평가 £65m ↔ €70~76m 병존 ⇒ 단일값 금지. ⭐ 신규 맥락(ESPN): **바이에른이 €65m 완전이적 옵션을 행사하지 않았다** ⇒ 현 호가는 이미 한 번 시장에서 거절된 가격대다. 계약 2031까지.\u000a\u000a[2026-08-24 21시] ⭐⭐ **Romano 08-24 오전층 + UEFA 45일 기산점이 처음 날짜로 특정됐다.**\u000a- **Romano 08-24 10:28 BST**(insidefutbol `724748`, 직접 fetch): 빌라가 「**in daily contact**」, 「**key days ahead**」. **첼시는 완전이적만** 수용하고 ATM은 「continue pushing」. 첼시 평가 **£65m**, 잭슨 계약 **2033**.\u000a- ⭐⭐ **신규·중대 — 45일 산술의 기산점 후보**: 「because **Morgan Rogers'' move to Chelsea was announced on 21 July**, a permanent deal between the clubs could now be regarded as a **player trade**, even on Deadline Day」 ⇒ **07-21 + 45일 = 09-04** 이므로 **09-01 마감일 딜이 45일 창 안에 들어간다.** 09시 리포트가 「근거 0」으로 남긴 항목에 처음 날짜가 붙었다.\u000a  ⛔ **단 이 문언의 캐리어는 3티어**(footballtransfers·sundayguardian)이고 **1차 규정문·1티어 확인은 여전히 0건**이다 ⇒ **「정본 확인」으로 표기 금지.** 다음 회차 최우선 검증 대상.\u000a- ⚠️ **발행일 주의**: 이 층(08-24 오전)은 20시 회차의 수집 창(≤12:58 BST) **안쪽**이다 — **20시가 놓친 층이고 21시 이후 신규층은 아니다.**\u000a- ⇒ **MEDIUM-HIGH 유지.** 왓킨스 매각 종속 구조 불변.\u000a\u000a[2026-08-25 21시] MEDIUM-HIGH 유지 — **단계·금액 이동 0. 그러나 하드 제약 1건이 드러났다.** ⭐⭐ **PL 「동일 구단 동시 임대 1명」 슬롯이 이미 가르나초(첼시)로 점유돼 있는데, 빌라가 첼시와 「이중 거래(잭슨 + 델랍)」를 추진한다는 보도가 나왔다**(Football Insider / Wayne Veysey 08-24 14:39 — 둘 중 하나는 loan-to-buy, 하나는 완전이적). ⇒ **잭슨·델랍 중 최소 한 명은 반드시 완전이적이어야 한다.** 이것이 09시의 「잭슨 loan-to-buy」 가설에 직접 제약을 건다 — 델랍이 임대로 오면 **잭슨은 완전이적만 가능**하다. 첼시 측 기조(완전이적만·£65m)와 이 제약이 **같은 방향**이라 구조적으로 정합한다. 빌라는 **SCR(스쿼드 코스트 비율) 제약으로 £65m 전액 지불 불가**라 감액 협상 중이다. [경쟁구도] **ATM이 되살아났다** — Romano 08-24 문언에 「Atlético Madrid **remain keen and keep pushing**」이 포함되고, 스페인 층(El Desmarque 08-24 22:18, Marca 인용)은 ATM 9번 자리 **「Jackson el gran favorito」**로 적는다. ⇒ 빌라 단독이 아니다. [2026-08-26 09시 — MEDIUM-HIGH → **HIGH 승격**] Romano(1티어) 08-25: 「Jackson remains Villa priority target as **club to club talks are starting**」 + 「Mateta 건은 잭슨 기회가 끝나기 전까진 아무것도 진행되지 않는다」 ⇒ §2 HIGH 요건(1티어가 협상 단계를 보도) 충족. Foot Mercato/Santi Aouna 08-25 17:11(갱신 08-26 01:48): **빌라가 보너스 포함 €70m 정식 오퍼 제출**, 첼시 요구 ~€75m, 첼시 수뇌부가 「sur le point d''être acceptée(수락 직전)」. 잔여 = 개인 조건. [경쟁구도] **빌라 우위(강화)** — Romano 「ATM은 임대를 선호했고, 완전이적을 커밋하지 않는 한 빌라가 더 현실적 행선지」. ⭐ **원장 정합 교정도 겸한다** — 같은 거래가 매도측(CHE #76)에서는 이미 HIGH였고 매수측만 MH로 남아 있었다. [2026-08-27] ⭐ Romano(1티어): 딜 최종 단계, 최대 £65m 패키지로 사실상 합의, 개인 조건 거의 타결, 메디컬 임박. | **[2026-08-27 21시 — HIGH 유지 · 금액 구조가 1티어 3곳으로 확정, 메디컬 단계 진입]** ⭐ **총액 최대 £65m = 초기 £47.5m(일시 전액 지급) + 애드온 £17.5m**(Ornstein/The Athletic) — **일시불 구조가 첼시가 잔액을 애드온으로 받아들인 이유**다. Sky Sports·Ornstein·Romano **1티어 3곳 교차** ⇒ 08-26 원장의 「Foot Mercato €70m 정식 오퍼」 단독층을 **이 값으로 대체**한다. **Pete O''Rourke: 잭슨이 08-27 빌라에서 메디컬 예정.** 선수는 빌라 프로젝트에 「yes」, 에메리와 통화 완료. ⭐ **완전이적이어야 하는 이유가 규정이다** — 가르나초가 이미 첼시에서 임대 중이고 **PL은 동일 PL 구단에서 2명 이상 임대 등록을 금지**하므로 임대 옵션이 원천 차단된다. [경쟁구도] **빌라 우위 → 사실상 종결.** ATM은 「빌라 오퍼를 맞출 수 없었다」로 정리되고(08-27 ATM 축 재확인: 첼시가 €70m 완전이적 고수 · ATM은 임대 고집 · 알레마니가 대안 공격수들에게 전화 — Cadena SER/El Larguero), 토트넘·나폴리는 탈락 확정. | [2026-08-28 09시] **Romano 「here we go」(08-27 저녁) — 서류 완료·메디컬 통과·계약 서명 예정.** 첼시 수령액 £65m 패키지(£47.5m 선불 + £17.5m 애드온, ≈€76m, 08-26(수) 클럽 간 합의). Plettenberg(Sky DE)가 「메디컬 후 최종 그린라이트, 당일 밤 서명 예정」으로 교차. 5년 계약 보도. **빌라 이적료 신기록**(구 기록 만잠비 £59.5m). 발단은 Santi Aouna(Foot Mercato) 08-25 £60m(€70m) 결정적 오퍼. **ATM은 임대만 원해 첼시가 선호하지 않았다 ⇒ §2-1 경쟁 소멸, 빌라 단독 우위.**\u000a[2026-08-28 21시] Romano 트윗 2093008009865667010 「Deal now done and documents completed … completed medical and now signs #AVFC contract」 — 09시의 「서명 예정」에서 메디컬·서류 완료로 진전. £65m 패키지.\u000a\u000a[2026-08-29 09시 · ⭐ CONFIRMED 승격 — 구단 1차 소스 직독] **avfc.co.uk 공식 발표를 브라우저로 직접 열어 확인했다**: 「Villa confirm Jackson signing」 — 「Aston Villa is delighted to announce the signing of Nicolas Jackson from Chelsea … has joined on a **permanent transfer**」. 슬러그 `/news/2026/august/28/signing-villa-confirm-jackson-signing/`(발행 2026-08-28 심야 UK). 후속 콘텐츠 2건도 동시 확인(「Jackson in claret and blue」 화보 · 「Jackson: I want to score a lot of goals」 인터뷰) ⇒ 발표 실체가 단일 기사가 아니라 **구단 콘텐츠 패키지**다. ⭐ 어제(08-28) 회차가 남긴 「avfc.co.uk 잭슨 공식 = 다음 회차 CONFIRMED 트리거」 이월 과제를 **이 회차에서 닫았다**. ⭐ 공식문이 에메리 재회(비야레알)와 25/26 **바이에른 임대(분데스리가+DFB 포칼 더블, 11골)** 를 함께 적어, 우리 원장의 「첼시 소속 · 25/26 바이에른」 전제와 정합한다. ⚠️ **구단 공식문은 이적료·계약연수·등번호를 공개하지 않았다** — 원장의 「총액 최대 £65m = 초기 £47.5m + 애드온 £17.5m」(08-27 합의층)는 **보도값이며 구단 원천으로 확인되지 않았다.** 정형 필드로 올리지 않는다.'),'Fabrizio Romano(1티어) 관심·에메리 각별 신뢰 확인 ; Football Insider(2티어) £60-65m 요구 ; Yahoo Sports "step up talks" ; SofaScore API play